package com.mediassistrover.backend.service.impl;
import com.mediassistrover.backend.dto.common.DeletionContracts.*;import com.mediassistrover.backend.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.nio.ByteBuffer;import java.util.*;import java.util.UUID;
@Service @RequiredArgsConstructor public class AccountHardDeleteService {private static final Set<String> OWNED=Set.of("RefreshToken.account_id","RevokedToken.account_id");private final JdbcTemplate jdbc;
 @Transactional(readOnly=true) public DeletionImpactResponse impact(UUID id){byte[]k=key(id);exists(k,id);var refs=refs(k);var b=refs.entrySet().stream().filter(e->!OWNED.contains(e.getKey())&&e.getValue()>0).map(e->e.getKey()+" has "+e.getValue()+" reference(s)").toList();return new DeletionImpactResponse(id,"Account",b.isEmpty(),b,Map.copyOf(refs));}
 @Transactional(propagation=Propagation.MANDATORY) public HardDeleteResponse delete(UUID id){byte[]k=key(id);lock(k,id);var i=impact(id);if(!i.canHardDelete())throw new ConflictException(String.join(", ",i.blockers()));var d=new LinkedHashMap<String,Long>();d.put("refreshTokenLinksCleared",(long)jdbc.update("UPDATE RefreshToken SET replaced_by_token_id=NULL WHERE account_id=?",k));d.put("refreshTokens",(long)jdbc.update("DELETE FROM RefreshToken WHERE account_id=?",k));d.put("revokedTokens",(long)jdbc.update("DELETE FROM RevokedToken WHERE account_id=?",k));d.put("Account",(long)jdbc.update("DELETE FROM Account WHERE account_id=?",k));return new HardDeleteResponse(id,"Account",Map.copyOf(d));}
 private Map<String,Long> refs(byte[]k){var o=new LinkedHashMap<String,Long>();var rows=jdbc.query("SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME='Account' ORDER BY TABLE_NAME,COLUMN_NAME",(r,n)->List.of(r.getString(1),r.getString(2)));for(var x:rows){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+x.get(0)+"` WHERE `"+x.get(1)+"`=?",Long.class,k);o.put(x.get(0)+"."+x.get(1),n==null?0:n);}return o;}private void exists(byte[]k,UUID id){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM Account WHERE account_id=?",Long.class,k);if(n==null||n==0)throw new ResourceNotFoundException("Account not found: "+id);}private void lock(byte[]k,UUID id){if(jdbc.query("SELECT account_id FROM Account WHERE account_id=? FOR UPDATE",(r,n)->r.getBytes(1),k).isEmpty())throw new ResourceNotFoundException("Account not found: "+id);}private static byte[]key(UUID id){return ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array();}}
